#include "coh_power_categories.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
static unsigned long long checks,cuts,mutations;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"categories check %d: %s\n",__LINE__,#x);exit(1);}}while(0)
typedef struct{unsigned calls;CohStatus status;}Digest;
static CohStatus digest(void*ctx,CohBytes b,uint8_t hash[32]){Digest*d=ctx;d->calls++;SHA256(b.data,b.size,hash);return d->status;}
static CohPowerCategoryDictionary out,before;static CohPowerCategoryWorkspace work;
static CohStatus parse(CohBytes input,const uint8_t hash[32],CohCostumeImportDigest*d,size_t budget,size_t retained){memset(&out,0xa5,sizeof(out));before=out;CohStatus s=coh_power_categories_read(input,1,hash,d,&out,&work,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&out,&before,sizeof(out)));return s;}
static uint32_t u32(FILE*f){uint8_t b[4];CHECK(fread(b,1,4,f)==4);return(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;}
static uint32_t at_word(const uint8_t*b,size_t i){return(uint32_t)b[i]|(uint32_t)b[i+1]<<8|(uint32_t)b[i+2]<<16|(uint32_t)b[i+3]<<24;}
static size_t skip_string(const uint8_t*b,size_t at){unsigned n=(unsigned)b[at]|(unsigned)b[at+1]<<8;return at+n+2+(4-(n+2)%4)%4;}
static void text(FILE*f,CohOriginText t){unsigned n=u32(f);char expected[260];CHECK(n==t.size&&n<260&&fread(expected,1,n,f)==n&&!memcmp(expected,out.text+t.offset,n)&&out.text[t.offset+n]==0);}
int main(int argc,char**argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");CHECK(f);unsigned cases=u32(f);for(unsigned ci=0;ci<cases;ci++){unsigned size=u32(f),begin=u32(f),status=u32(f),projection_size=u32(f);CHECK(size&&size<=COH_CATEGORY_INPUT_MAX);uint8_t*data=malloc(size),*changed=malloc(size);CHECK(data&&changed&&fread(data,1,size,f)==size);long projection_begin=ftell(f);uint8_t hash[32];SHA256(data,size,hash);Digest ctx={0,COH_OK};CohCostumeImportDigest d={digest,&ctx,sizeof(ctx),0};CHECK(parse((CohBytes){data,size},hash,&d,COH_CATEGORY_RAM_MAX,0)==(CohStatus)status);
 if(status){CHECK(!ctx.calls&&fseek(f,(long)projection_size,SEEK_CUR)==0);}else{
 CHECK(ctx.calls==1&&out.raw_schema_validated&&out.schema_crc_matched&&!out.complete_power_dictionary&&!out.actor_authority&&out.source_lease==1&&!memcmp(hash,out.input_sha256,32));CHECK(u32(f)==out.count&&u32(f)==out.dependency_count&&u32(f)==out.set_count&&u32(f)==out.index_count);
 for(unsigned i=0;i<out.count;i++){CohPowerCategoryEntry*e=&out.entries[i];for(unsigned k=0;k<5;k++)text(f,e->fields[k]);for(unsigned k=0;k<e->set_count;k++)text(f,out.sets[e->set_first+k]);CHECK(u32(f)==e->set_count&&u32(f)==e->index_count);for(unsigned k=0;k<e->index_count;k++)CHECK(u32(f)==out.indices[e->index_first+k]);uint32_t index=999;CohOriginText name=e->fields[1];char lower[260];for(unsigned j=0;j<name.size;j++){unsigned c=(unsigned char)out.text[name.offset+j];lower[j]=(char)(c>='A'&&c<='Z'?c+32:c);}CHECK(coh_power_categories_find(&out,(CohBytes){(const uint8_t*)lower,name.size},&index)==COH_OK&&index==i);}
 CHECK(ftell(f)==projection_begin+(long)projection_size);CohPowerCategoryDictionary*good=malloc(sizeof(*good));CHECK(good);*good=out;
 for(size_t n=1;n<size;n+=4096){ctx.calls=0;CHECK(parse((CohBytes){data,n},hash,&d,COH_CATEGORY_RAM_MAX,0)!=COH_OK&&ctx.calls==0);cuts++;}
 for(size_t n=0;n<size;n+=size/97+1){memcpy(changed,data,size);changed[n]^=255;CHECK(parse((CohBytes){changed,size},hash,&d,COH_CATEGORY_RAM_MAX,0)!=COH_OK);mutations++;}
 if(good->count){size_t row=begin+8;size_t points[4]={begin+4,row+4,0,0};size_t pos=row+4;for(unsigned i=0;i<5;i++)pos=skip_string(data,pos);points[2]=pos;unsigned sets=at_word(data,pos);pos+=4;for(unsigned i=0;i<sets;i++)pos=skip_string(data,pos);points[3]=pos;uint32_t values[]={COH_CATEGORY_MAX+1,260,COH_CATEGORY_REFS_MAX+1,COH_CATEGORY_REFS_MAX+1};for(unsigned i=0;i<4;i++){memcpy(changed,data,size);if(i==1){changed[points[i]]=4;changed[points[i]+1]=1;}else for(unsigned j=0;j<4;j++)changed[points[i]+j]=(uint8_t)(values[i]>>(8*j));uint8_t bad_hash[32];SHA256(changed,size,bad_hash);ctx.calls=0;CHECK(parse((CohBytes){changed,size},bad_hash,&d,COH_CATEGORY_RAM_MAX,0)==COH_LIMIT&&ctx.calls==0);}}
 size_t exact=sizeof(out)+sizeof(work)+sizeof(d)+sizeof(ctx)+32+COH_CATEGORY_STACK_RESERVE+size;CHECK(exact<=COH_CATEGORY_RAM_MAX);CHECK(parse((CohBytes){data,size},hash,&d,exact,0)==COH_OK);ctx.calls=0;CHECK(parse((CohBytes){data,size},hash,&d,exact,1)==COH_LIMIT&&ctx.calls==0);ctx.status=COH_CANCELLED;CHECK(parse((CohBytes){data,size},hash,&d,COH_CATEGORY_RAM_MAX,0)==COH_CANCELLED);ctx.status=COH_OK;d.scratch_reserve=SIZE_MAX;CHECK(parse((CohBytes){data,size},hash,&d,COH_CATEGORY_RAM_MAX,0)==COH_LIMIT);d.scratch_reserve=0;CHECK(coh_power_categories_read((CohBytes){data,size},1,hash,&d,&out,(CohPowerCategoryWorkspace*)&out,COH_CATEGORY_RAM_MAX,0)==COH_INVALID);d.context=&out;d.context_bytes=1;CHECK(coh_power_categories_read((CohBytes){data,size},1,hash,&d,&out,&work,COH_CATEGORY_RAM_MAX,0)==COH_INVALID);out=*good;uint32_t index=999;CHECK(coh_power_categories_find(&out,(CohBytes){(const uint8_t*)"unknown_missing_category",24},&index)==COH_NOT_FOUND&&index==999);CHECK(coh_power_categories_find(&out,(CohBytes){(const uint8_t*)"\xff",1},&index)==COH_UNSUPPORTED);CHECK(coh_power_categories_find(&out,(CohBytes){(const uint8_t*)"a",1},&out.count)==COH_INVALID);free(good);
 }
 free(changed);free(data);
 }CHECK(fgetc(f)==EOF);fclose(f);printf("{\"checks\":%llu,\"cases\":%u,\"cuts\":%llu,\"mutations\":%llu,\"owner_bytes\":%zu,\"complete_power_dictionary\":false,\"actor_authority\":false}\n",checks,cases,cuts,mutations,sizeof(out));return 0;}
